create or replace function public.audit_row_change() returns trigger language plpgsql security definer set search_path=public as $$ declare v_tour uuid; begin v_tour:=case tg_table_name when 'tours' then coalesce(new.id,old.id) when 'teams' then coalesce(new.tour_id,old.tour_id) when 'tour_players' then coalesce(new.tour_id,old.tour_id) when 'rounds' then coalesce(new.tour_id,old.tour_id) else null end; insert into public.audit_log(tour_id,actor_user_id,entity_type,entity_id,action,old_data,new_data) values(v_tour,(select auth.uid()),tg_table_name,coalesce(new.id,old.id),tg_op,to_jsonb(old),to_jsonb(new)); return coalesce(new,old); end;$$;
create trigger audit_tours after insert or update or delete on public.tours for each row execute function public.audit_row_change(); create trigger audit_teams after insert or update or delete on public.teams for each row execute function public.audit_row_change(); create trigger audit_tour_players after insert or update or delete on public.tour_players for each row execute function public.audit_row_change(); create trigger audit_rounds after insert or update or delete on public.rounds for each row execute function public.audit_row_change();
